from app.services import ledger


def issue_refund(payment_id: str, amount_cents: int) -> dict:
    """Issue a refund for part or all of a payment, never more than was paid."""
    payment = ledger.find(payment_id)
    if amount_cents > payment.amount_cents:
        raise ValueError("refund exceeds payment")
    return ledger.record_refund(payment_id, amount_cents)
